import random, struct, sys, zlib
sys.path.insert(0, "/app")
from main import solve

def digest_of(payloads):
    c = 0
    for p in payloads:
        c = zlib.crc32(p, c)
    return c & 0xffffffff

# ---- independent model ----
def model(pages_hex, checkpoint, log):
    pages = [bytearray(bytes.fromhex(p)) for p in pages_hex]
    pos = prev = last = 0
    inc = {}
    n = len(log)
    while n - pos >= 13:
        plen, seq, kind, txid = struct.unpack_from("<IIBI", log, pos)
        if plen > 4096 or pos + 17 + plen > n: break
        payload = log[pos+13:pos+13+plen]
        if struct.unpack_from("<I", log, pos+13+plen)[0] != zlib.crc32(log[pos:pos+13+plen]) & 0xffffffff: break
        if not (seq > prev > -1 and seq > 0): break
        if txid == 0: break
        if kind == 1:
            if plen: break
        elif kind == 2:
            if plen < 6: break
            pi, off, cnt = struct.unpack_from("<HHH", payload)
            if cnt == 0 or plen != 6+cnt or pi >= len(pages) or off+cnt > len(pages[pi]): break
        elif kind == 3:
            if plen != 8: break
        elif kind == 4:
            if plen: break
        else: break
        if kind == 1: inc[txid] = []
        elif kind == 2:
            if txid in inc: inc[txid].append((payload, pi, off))
        elif kind == 3:
            lst = inc.pop(txid, None)
            if lst is not None:
                cw, dw = struct.unpack("<II", payload)
                if len(lst) == cw and digest_of([p for p, _, _ in lst]) == dw and seq > checkpoint:
                    for p, pi, off in lst:
                        pages[pi][off:off+len(p)-6] = p[6:]
        else: inc.pop(txid, None)
        prev = last = seq
        pos += 17 + plen
    return {"pages": [p.hex() for p in pages], "valid_bytes": pos, "last_seq": last}

def rec(seq, kind, txid, payload=b""):
    h = struct.pack("<IIBI", len(payload), seq, kind, txid)
    return h + payload + struct.pack("<I", zlib.crc32(h+payload) & 0xffffffff)

def gen_case(rng):
    npages = rng.randint(1, 3)
    plen_page = rng.randint(4, 12)
    pages = ["%02x" % rng.randrange(256) * 0 + "00"]  # placeholder
    pages = [bytes(rng.randrange(256) for _ in range(plen_page)).hex() for _ in range(npages)]
    tx_payloads = {}  # txid -> list of payloads currently staged (model of what we built)
    recs = []
    seq = 0
    for _ in range(rng.randint(0, 14)):
        seq += rng.randint(1, 3)
        txid = rng.randint(1, 3)
        op = rng.choice(["begin", "patch", "commit", "abort", "patch", "commit"])
        if op == "begin":
            recs.append(rec(seq, 1, txid)); tx_payloads[txid] = []
        elif op == "patch":
            pi = rng.randrange(npages)
            cnt = rng.randint(1, plen_page)
            off = rng.randint(0, plen_page - cnt)
            data = bytes(rng.randrange(256) for _ in range(cnt))
            p = struct.pack("<HHH", pi, off, cnt) + data
            recs.append(rec(seq, 2, txid, p))
            tx_payloads.setdefault(txid, None)
            if tx_payloads[txid] is not None: tx_payloads[txid].append(p)
        elif op == "commit":
            lst = tx_payloads.get(txid)
            if lst is not None and rng.random() < 0.85:
                cnt, dg = len(lst), digest_of(lst)
                if rng.random() < 0.15:  # occasional bad seal
                    if rng.random() < 0.5: cnt += rng.randint(1, 2)
                    else: dg ^= 1 << rng.randrange(32)
            else:
                cnt, dg = rng.randint(0, 3), rng.randrange(2**32)
            recs.append(rec(seq, 3, txid, struct.pack("<II", cnt, dg)))
            if txid in tx_payloads: tx_payloads[txid] = None
        else:
            recs.append(rec(seq, 4, txid))
            if txid in tx_payloads: tx_payloads[txid] = None
    log = b"".join(recs)
    # inject corruption / torn tail sometimes
    r = rng.random()
    if r < 0.18 and log:
        # corrupt one byte at random position
        i = rng.randrange(len(log))
        log = log[:i] + bytes([log[i] ^ (1 << rng.randrange(8))]) + log[i+1:]
    elif r < 0.30 and log:
        log = log[:rng.randrange(len(log) + 1)]  # torn tail
    elif r < 0.38:
        log += bytes(rng.randrange(256) for _ in range(rng.randint(1, 20)))  # garbage tail
    elif r < 0.44:
        # plen override: huge length on first record
        if len(log) >= 4:
            log = struct.pack("<I", rng.choice([4097, 5000, 2**32-1])) + log[4:]
    checkpoint = rng.choice([0, 1, 2, 3, rng.randint(0, seq + 2) if seq else 0, max(seq - 1, 0), seq, seq + 5])
    return {"pages": pages, "checkpoint": checkpoint, "log": log.hex()}

rng = random.Random(20241008)
for i in range(4000):
    req = gen_case(rng)
    exp = model(req["pages"], req["checkpoint"], bytes.fromhex(req["log"]))
    got = solve(req)
    if got != exp:
        print("MISMATCH at case", i)
        print("req:", req)
        print("got:", got)
        print("exp:", exp)
        sys.exit(1)
    assert got["valid_bytes"] <= len(bytes.fromhex(req["log"]))
    assert all(len(bytes.fromhex(g)) == len(bytes.fromhex(p)) for g, p in zip(got["pages"], req["pages"]))
print("4000 randomized differential cases passed.")
